const field = ctx.newField();
const poleY = -768;
const equatorY = 768;
for (let y = 0; y < ctx.size; y++) {
  const southwardness = (ctx.originY + y - poleY) / (equatorY - poleY);
  const warmth = Math.max(0, Math.min(1, southwardness));
  for (let x = 0; x < ctx.size; x++) {
    field[y * ctx.size + x] = warmth;
  }
}
return field;
